#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ── Knock Management API helpers (wizard-specific, below the marker) ──────
KNOCK_MAPI="https://control.knock.app/v1"
KNOCK_ENV_SLUG="development"

# mapi METHOD PATH [JSON_BODY]: calls the Management API, prints the body,
# fails (and shows the error) on a non-2xx status.
mapi() {
  local method="$1" path="$2" body="${3:-}" out status
  out=$(mktemp)
  if [[ -n "$body" ]]; then
    status=$(curl -sS -o "$out" -w '%{http_code}' -X "$method" "$KNOCK_MAPI$path" \
      -H "Authorization: Bearer $KNOCK_SERVICE_TOKEN" -H "Content-Type: application/json" \
      --data-binary "$body")
  else
    status=$(curl -sS -o "$out" -w '%{http_code}' -X "$method" "$KNOCK_MAPI$path" \
      -H "Authorization: Bearer $KNOCK_SERVICE_TOKEN")
  fi
  if [[ "$status" != 2* ]]; then
    warn "$method $path → HTTP $status" >&2
    note "$(cat "$out")" >&2
    rm -f "$out"
    return 1
  fi
  cat "$out"; rm -f "$out"
}

# upsert_feed_workflow KEY NAME CATEGORY MARKDOWN ACTION_URL: creates or
# updates a one-step in-app feed workflow and commits it to Development.
upsert_feed_workflow() {
  local key="$1" name="$2" category="$3" markdown="$4" action_url="$5" body
  body=$(jq -n --arg name "$name" --arg cat "$category" --arg ch "$FEED_CHANNEL_KEY" \
    --arg md "$markdown" --arg url "$action_url" '{
      workflow: {
        name: $name,
        categories: [$cat],
        steps: [{
          type: "channel", ref: "in_app_feed_1", name: "Notification Feed",
          channel_key: $ch,
          template: { markdown_body: $md, action_url: $url }
        }]
      }
    }')
  # Workflows may only use categories already in the account's catalog.
  # This PUT is idempotent: it returns the existing category if present.
  mapi PUT "/preference_categories/$category" >/dev/null || return 1
  printf '  %s✓ category%s %s\n' "$GREEN" "$RESET" "$category"
  mapi PUT "/workflows/$key?environment=$KNOCK_ENV_SLUG&commit=true&commit_message=Knock+spike+%2328%3A+$key" "$body" \
    | jq -r '"  ✓ committed \(.workflow.key): categories \(.workflow.categories | tostring)"' || return 1
  # New workflows can start inactive; make sure triggers aren't skipped.
  mapi PUT "/workflows/$key/activate?environment=$KNOCK_ENV_SLUG" '{"status":true}' \
    | jq -r '"  ✓ active: \(.workflow.active)"'
}

run_wizard() {

TOTAL_STAGES=5

banner "Knock: workflows and default preferences for the Knock spike (#28)"

command -v jq >/dev/null 2>&1 || { warn "this wizard needs jq (brew install jq)"; exit 1; }
KNOCK_FEED_CHANNEL_ID=$(_existing KNOCK_FEED_CHANNEL_ID || true)
[[ -n "$KNOCK_FEED_CHANNEL_ID" ]] || { warn "KNOCK_FEED_CHANNEL_ID missing from $ENV_FILE; run scripts/knock-setup.sh first"; exit 1; }

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Service token (Management API)"
say "Workflows and environment defaults are set through Knock's Management API,"
say "so instead of clicking through the workflow builder, this wizard does it for you."
say "It needs a service token: an account-level token, separate from the API keys."
open_url "https://dashboard.knock.app"
step "Open your account settings (click your account name, top left) → Service tokens."
step "Click Generate token and name it 'cadence-dev'."
note "Docs: https://docs.knock.app/developer-tools/service-tokens. The exact clicks may differ slightly."
step "Copy the token (starts knock_st_)."
ask_secret KNOCK_SERVICE_TOKEN "Paste the service token:"
if who=$(mapi GET /whoami); then
  say "$(jq -r '"Token works: account \(.account_name // .account_slug // "ok")"' <<<"$who")"
  write_env KNOCK_SERVICE_TOKEN "$KNOCK_SERVICE_TOKEN"
else
  warn "The token was rejected. Re-run the wizard with a fresh token."; exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Find the feed channel's key"
say "Workflow steps reference a channel by key, but .env holds its ID. Looking it up…"
channels=$(mapi GET "/channels?limit=100") || exit 1
FEED_CHANNEL_KEY=$(jq -r --arg id "$KNOCK_FEED_CHANNEL_ID" '.entries[] | select(.id == $id) | .key' <<<"$channels")
if [[ -z "$FEED_CHANNEL_KEY" ]]; then
  warn "No channel has ID $KNOCK_FEED_CHANNEL_ID. Channels found:"
  jq -r '.entries[] | "    \(.key)  \(.type)  \(.id)"' <<<"$channels"
  ask FEED_CHANNEL_KEY "Type the in-app feed channel's key:"
fi
say "Feed channel key: $BOLD$FEED_CHANNEL_KEY$RESET"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Workflow: discussion-reply"
say "Discussion Reply → question author. Category 'discussion', one in-app feed step."
note "Template: **{{ data.replier_name }}** replied to your question in *{{ data.lesson_title }}*"
if confirm "Create or update and commit 'discussion-reply' in Development"; then
  upsert_feed_workflow discussion-reply "Discussion Reply" discussion \
    '**{{ data.replier_name }}** replied to your question in *{{ data.lesson_title }}*' \
    '{{ data.url }}' || SKIPPED+=("Workflow discussion-reply (Management API call failed)")
else
  SKIPPED+=("Workflow discussion-reply")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Workflow: new-enrollment"
say "New Enrollment → Instructor. Category 'new-enrollment', one in-app feed step."
note "Template: **{{ data.student_name }}** enrolled in *{{ data.course_title }}*"
if confirm "Create or update and commit 'new-enrollment' in Development"; then
  upsert_feed_workflow new-enrollment "New Enrollment" new-enrollment \
    '**{{ data.student_name }}** enrolled in *{{ data.course_title }}*' \
    '{{ data.url }}' || SKIPPED+=("Workflow new-enrollment (Management API call failed)")
else
  SKIPPED+=("Workflow new-enrollment")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Environment default: new-enrollment off"
say "Makes New Enrollment opt-in: off for everyone unless they turn it on."
current=$(mapi GET "/environments/$KNOCK_ENV_SLUG/defaults") || current='{"preference_set":null}'
note "Current Development defaults: $(jq -c '.preference_set' <<<"$current")"
warn "This replaces the Development default preference set in full. It applies at once and isn't committed."
# Keep any existing defaults; only force categories.new-enrollment = false.
next=$(jq -c '{preference_set: ((.preference_set // {}) | .categories = ((.categories // {}) + {"new-enrollment": false}))}' <<<"$current")
note "New defaults: $(jq -c '.preference_set' <<<"$next")"
if confirm "Write these defaults to Development"; then
  if mapi PUT "/environments/$KNOCK_ENV_SLUG/defaults" "$next" >/dev/null; then
    say "✓ Default set: new-enrollment is off unless a user opts in."
  else
    SKIPPED+=("Environment default categories.new-enrollment=false (API call failed)")
  fi
else
  SKIPPED+=("Environment default categories.new-enrollment=false")
fi
pause

finish
note "Next: npm run dev, then open http://localhost:5173/prototype/knock and run the four checks."
note "Revoke the service token after the spike if you won't reuse it."
printf '\n'
}

run_wizard "$@"; exit
